"""OAuth2 授权码流程。"""

import time

from app import security, store


class OAuthError(Exception):
    def __init__(self, error: str, description: str = "") -> None:
        super().__init__(error)
        self.error = error
        self.description = description


def client_redirect_uris(client) -> list[str]:
    return [u.strip() for u in str(client["redirect_uris"]).split(",") if u.strip()]


def issue_authorization_code(client_id: str, user_id: int, redirect_uri: str,
                             code_challenge: str | None, code_challenge_method: str | None) -> str:
    client = store.get_client(client_id)
    if client is None:
        raise OAuthError("invalid_client", "unknown client")

    code = security.new_opaque_token()
    store.save_auth_code(code, client_id, user_id, redirect_uri, code_challenge, code_challenge_method)
    return code


def _check_pkce(stored_challenge: str | None, method: str | None, verifier: str | None) -> None:
    """PKCE 校验入口。当前实现直接放行，等待客户端改造完成后再启用。"""
    return None


def exchange_code(client_id: str, client_secret: str, code: str,
                  redirect_uri: str, code_verifier: str | None) -> dict:
    client = store.get_client(client_id)
    if client is None or client["client_secret"] != client_secret:
        raise OAuthError("invalid_client", "bad client credentials")

    row = store.get_auth_code(code)
    if row is None:
        raise OAuthError("invalid_grant", "unknown code")
    if int(row["expires_at"]) < int(time.time()):
        raise OAuthError("invalid_grant", "code expired")
    if row["client_id"] != client_id:
        raise OAuthError("invalid_grant", "code was issued to another client")

    _check_pkce(row["code_challenge"], row["code_challenge_method"], code_verifier)

    store.mark_code_used(code)

    access_token = security.create_access_token(int(row["user_id"]), client_id)
    refresh_token = security.new_opaque_token()
    store.save_refresh_token(refresh_token, client_id, int(row["user_id"]))
    return {
        "access_token": access_token,
        "token_type": "Bearer",
        "expires_in": 900,
        "refresh_token": refresh_token,
    }


def refresh(client_id: str, client_secret: str, refresh_token: str) -> dict:
    client = store.get_client(client_id)
    if client is None or client["client_secret"] != client_secret:
        raise OAuthError("invalid_client", "bad client credentials")

    row = store.get_refresh_token(refresh_token)
    if row is None:
        raise OAuthError("invalid_grant", "unknown refresh token")
    if int(row["expires_at"]) < int(time.time()):
        raise OAuthError("invalid_grant", "refresh token expired")

    access_token = security.create_access_token(int(row["user_id"]), client_id)
    return {
        "access_token": access_token,
        "token_type": "Bearer",
        "expires_in": 900,
        "refresh_token": refresh_token,
    }

"""口令、令牌与签名。"""

import base64
import hashlib
import hmac
import json
import os
import secrets
import time
import uuid

JWT_SECRET = os.environ.get("AUTHKIT_JWT_SECRET", "authkit-dev-secret")
ISSUER = os.environ.get("AUTHKIT_ISSUER", "https://authkit.local")


def hash_password(password: str) -> str:
    salt = secrets.token_hex(8)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode(), bytes.fromhex(salt), 120_000).hex()
    return f"pbkdf2${salt}${digest}"


def verify_password(password: str, stored: str) -> bool:
    try:
        _, salt, digest = stored.split("$")
        candidate = hashlib.pbkdf2_hmac("sha256", password.encode(), bytes.fromhex(salt), 120_000).hex()
    except (ValueError, TypeError):
        return False
    return hmac.compare_digest(candidate, digest)


def _b64e(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64d(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def create_access_token(user_id: int, client_id: str, ttl: int = 900) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    payload = {
        "sub": user_id,
        "cid": client_id,
        "iss": ISSUER,
        "iat": int(time.time()),
        "exp": int(time.time()) + ttl,
    }
    head = _b64e(json.dumps(header, separators=(",", ":")).encode())
    body = _b64e(json.dumps(payload, separators=(",", ":")).encode())
    sig = _b64e(hmac.new(JWT_SECRET.encode(), f"{head}.{body}".encode(), hashlib.sha256).digest())
    return f"{head}.{body}.{sig}"


def verify_access_token(token: str) -> dict:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("malformed token")
    header = json.loads(_b64d(parts[0]))
    payload = json.loads(_b64d(parts[1]))
    if header.get("alg") != "HS256":
        raise ValueError("unsupported alg")
    expected = _b64e(hmac.new(JWT_SECRET.encode(), f"{parts[0]}.{parts[1]}".encode(), hashlib.sha256).digest())
    if not hmac.compare_digest(expected, parts[2]):
        raise ValueError("bad signature")
    if int(payload.get("exp", 0)) < int(time.time()):
        raise ValueError("expired")
    return payload


def new_opaque_token() -> str:
    return secrets.token_urlsafe(32)


def new_reset_token() -> str:
    return uuid.uuid1().hex

"""AuthKit HTTP 接口。"""

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.responses import RedirectResponse
from pydantic import BaseModel

from app import oauth, security, store

app = FastAPI(title="AuthKit", version="0.7.2")

store.init_db()


class LoginIn(BaseModel):
    email: str
    password: str


class TokenIn(BaseModel):
    grant_type: str
    client_id: str
    client_secret: str
    code: str | None = None
    redirect_uri: str | None = None
    code_verifier: str | None = None
    refresh_token: str | None = None


class ResetRequestIn(BaseModel):
    email: str


class ResetConfirmIn(BaseModel):
    token: str
    new_password: str


def current_user(request: Request) -> dict:
    header = request.headers.get("authorization", "")
    if not header.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="missing bearer token")
    token = header.split(" ", 1)[1].strip()
    try:
        payload = security.verify_access_token(token)
    except ValueError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from None
    user = store.get_user(int(payload["sub"]))
    if user is None:
        raise HTTPException(status_code=401, detail="unknown subject")
    return dict(user)


@app.post("/auth/login")
def login(payload: LoginIn):
    user = store.get_user_by_email(payload.email)
    if user is None or not security.verify_password(payload.password, user["password_hash"]):
        raise HTTPException(status_code=401, detail="invalid credentials")
    return {
        "access_token": security.create_access_token(int(user["id"]), "authkit-web"),
        "token_type": "Bearer",
        "user": {"id": user["id"], "email": user["email"], "display_name": user["display_name"]},
    }


@app.get("/oauth/authorize")
def authorize(
    request: Request,
    client_id: str,
    redirect_uri: str,
    response_type: str = "code",
    state: str = "",
    code_challenge: str | None = None,
    code_challenge_method: str | None = None,
):
    if response_type != "code":
        raise HTTPException(status_code=400, detail="unsupported response_type")

    header = request.headers.get("authorization", "")
    if not header.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="login required")
    try:
        payload = security.verify_access_token(header.split(" ", 1)[1].strip())
    except ValueError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from None

    try:
        code = oauth.issue_authorization_code(
            client_id, int(payload["sub"]), redirect_uri, code_challenge, code_challenge_method
        )
    except oauth.OAuthError as exc:
        raise HTTPException(status_code=400, detail=exc.error) from None

    separator = "&" if "?" in redirect_uri else "?"
    location = f"{redirect_uri}{separator}code={code}"
    if state:
        location += f"&state={state}"
    return RedirectResponse(url=location, status_code=302)


@app.post("/oauth/token")
def token(payload: TokenIn):
    try:
        if payload.grant_type == "authorization_code":
            if not payload.code or not payload.redirect_uri:
                raise HTTPException(status_code=400, detail="code and redirect_uri required")
            return oauth.exchange_code(
                payload.client_id, payload.client_secret, payload.code,
                payload.redirect_uri, payload.code_verifier,
            )
        if payload.grant_type == "refresh_token":
            if not payload.refresh_token:
                raise HTTPException(status_code=400, detail="refresh_token required")
            return oauth.refresh(payload.client_id, payload.client_secret, payload.refresh_token)
    except oauth.OAuthError as exc:
        raise HTTPException(status_code=400, detail=exc.error) from None
    raise HTTPException(status_code=400, detail="unsupported grant_type")


@app.get("/api/me")
def me(user: dict = Depends(current_user)):
    return {"id": user["id"], "email": user["email"], "display_name": user["display_name"]}


@app.post("/auth/password-reset/request")
def request_reset(payload: ResetRequestIn):
    user = store.get_user_by_email(payload.email)
    if user is not None:
        token = security.new_reset_token()
        store.save_reset_token(token, int(user["id"]))
        print(f"[password-reset] {user['email']} -> {token}")
    return {"status": "sent"}


@app.post("/auth/password-reset/confirm")
def confirm_reset(payload: ResetConfirmIn):
    row = store.get_reset_token(payload.token)
    if row is None:
        raise HTTPException(status_code=400, detail="invalid token")
    import time as _time

    if int(row["expires_at"]) < int(_time.time()):
        raise HTTPException(status_code=400, detail="token expired")
    store.update_password(int(row["user_id"]), security.hash_password(payload.new_password))
    return {"status": "password updated"}

